USE [Hyperyek]; IF OBJECT_ID(N'dbo.ExternalOrderMappings',N'U') IS NULL CREATE TABLE dbo.ExternalOrderMappings (Id bigint IDENTITY PRIMARY KEY,ConnectionId bigint NOT NULL,ShopId int NOT NULL,HyperSaleOrderId bigint NULL,ExternalOrderId nvarchar(200) NOT NULL,ExternalParcelId nvarchar(200) NULL,Status tinyint NOT NULL DEFAULT(0),LastSyncAtUtc datetime2 NULL,CONSTRAINT UQ_ExternalOrderMappings UNIQUE(ConnectionId,ExternalOrderId)); IF OBJECT_ID(N'dbo.InventoryReservationLogs',N'U') IS NULL CREATE TABLE dbo.InventoryReservationLogs (Id bigint IDENTITY PRIMARY KEY,ShopId int NOT NULL,HyperProductId int NOT NULL,ReservationKey nvarchar(200) NOT NULL,Quantity decimal(18,3) NOT NULL,Status tinyint NOT NULL DEFAULT(0),Source varchar(50) NOT NULL,CreatedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),ReleasedAtUtc datetime2 NULL,CONSTRAINT UQ_InventoryReservationLogs UNIQUE(ShopId,ReservationKey)); IF OBJECT_ID(N'dbo.IntegrationEventAudits',N'U') IS NULL CREATE TABLE dbo.IntegrationEventAudits (Id bigint IDENTITY PRIMARY KEY,ConnectionId bigint NULL,Direction varchar(20) NOT NULL,EventType nvarchar(200) NOT NULL,ExternalEventId nvarchar(200) NOT NULL,PayloadHash varchar(128) NOT NULL,SignatureValid bit NOT NULL,CorrelationId varchar(100) NULL,ReceivedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UQ_IntegrationEventAudits UNIQUE(ConnectionId,ExternalEventId,Direction));
